SET @app_actor_id = 'system:migration';
CREATE TABLE application_session_contexts (id varchar(64) PRIMARY KEY,session_id varchar(64) NOT NULL,user_id varchar(64) NOT NULL,tenant_id varchar(64) NOT NULL,membership_id varchar(64) NOT NULL,application_id varchar(64) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY application_session_contexts_session_tenant_unique(session_id,tenant_id),KEY application_session_contexts_lookup_idx(user_id,tenant_id,membership_id,session_id),CONSTRAINT application_session_contexts_session_fk FOREIGN KEY(session_id) REFERENCES identity_sessions(id),CONSTRAINT application_session_contexts_user_fk FOREIGN KEY(user_id) REFERENCES identity_users(id),CONSTRAINT application_session_contexts_tenant_fk FOREIGN KEY(tenant_id) REFERENCES tenants(id),CONSTRAINT application_session_contexts_membership_fk FOREIGN KEY(membership_id) REFERENCES tenant_memberships(id),CONSTRAINT application_session_contexts_application_fk FOREIGN KEY(application_id) REFERENCES applications(id));
CREATE TRIGGER application_session_contexts_audit_bi BEFORE INSERT ON application_session_contexts FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL ELSE NULLIF(TRIM(@app_actor_id),'') END;
CREATE TRIGGER application_session_contexts_audit_bu BEFORE UPDATE ON application_session_contexts FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER application_session_contexts_audit_bd BEFORE DELETE ON application_session_contexts FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
